package com.cestasdamel.erp.controller; import com.cestasdamel.erp.dto.Requests.ManualTransaction; import com.cestasdamel.erp.dto.Responses.FinancialView; import com.cestasdamel.erp.service.FinanceService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.*;
@RestController @RequestMapping("/financial-transactions") @RequiredArgsConstructor public class FinanceController {private final FinanceService service;@GetMapping List<FinancialView> list(){return service.list();}@GetMapping("/balance") Map<String,BigDecimal> balance(){return Map.of("balance",service.balance());}@PostMapping FinancialView manual(@Valid @RequestBody ManualTransaction r){return service.manual(r);}}
